urlset:
{%- assign pg_sm_pages = site.pages | where_exp: "p", "p.sitemap != false" -%}
{%- for pg_p in pg_sm_pages %}

    {{ pg_p.url | absolute_url }}
    {%- if pg_p.translation_key -%}
      {%- assign pg_sm_translations = site.pages | concat: site.documents | where: "translation_key", pg_p.translation_key -%}
      {%- for pg_tr in pg_sm_translations %}

      {%- endfor -%}
    {%- endif %}

{%- endfor %}
{%- for pg_coll in site.collections %}
  {%- assign pg_coll_docs = pg_coll.docs | where_exp: "d", "d.sitemap != false" -%}
  {%- for pg_p in pg_coll_docs %}

    {{ pg_p.url | absolute_url }}
    {%- if pg_p.translation_key -%}
      {%- assign pg_sm_translations = site.pages | concat: site.documents | where: "translation_key", pg_p.translation_key -%}
      {%- for pg_tr in pg_sm_translations %}

      {%- endfor -%}
    {%- endif %}

  {%- endfor %}
{%- endfor %}
